Reveal.on('fragmentshown', (event) =&gt; {
  if (event.fragment.classList.contains("my-class")) {
    // apply the change
  }
});

Reveal.on('fragmenthidden', (event) =&gt; {
  if (event.fragment.classList.contains("my-class")) {
    // undo the change
  }
});


